import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { Apple, Car, Clock, Flag, Hash, Lightbulb, PawPrint, Search, Smile, Trophy, User } from 'lucide-react';

// The full Unicode emoji set (generated by scripts/gen-emoji.py), loaded on first open so it
// does not weigh on the chat's start-up.
type EmojiGroup = { group: string; emojis: [string, string][] };
let dataPromise: Promise<EmojiGroup[]> | null = null;
const loadEmojis = () => (dataPromise ??= import('../../pulse/emojiData.json').then((m) => m.default as unknown as EmojiGroup[]));

const RECENT_KEY = 'pulse:recentEmojis';
const RECENT_MAX = 32;

function readRecent(): string[] {
  try {
    const v = JSON.parse(localStorage.getItem(RECENT_KEY) ?? '[]');
    return Array.isArray(v) ? v.filter((e) => typeof e === 'string').slice(0, RECENT_MAX) : [];
  } catch {
    return [];
  }
}

function rememberEmoji(emoji: string) {
  try {
    const next = [emoji, ...readRecent().filter((e) => e !== emoji)].slice(0, RECENT_MAX);
    localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  } catch {
    // storage blocked: recents just are not kept
  }
}

const GROUP_ICONS: Record<string, React.ReactNode> = {
  'Recently used': <Clock size={16} />,
  'Smileys & Emotion': <Smile size={16} />,
  'People & Body': <User size={16} />,
  'Animals & Nature': <PawPrint size={16} />,
  'Food & Drink': <Apple size={16} />,
  'Travel & Places': <Car size={16} />,
  Activities: <Trophy size={16} />,
  Objects: <Lightbulb size={16} />,
  Symbols: <Hash size={16} />,
  Flags: <Flag size={16} />,
};

interface EmojiPickerProps {
  onPick: (emoji: string) => void;
  onClose: () => void;
  /** Viewport point to open at (the picker keeps itself on screen). */
  x: number;
  y: number;
  /** Close after the first pick (reactions) or stay open (typing a message). */
  closeOnPick?: boolean;
}

/** WhatsApp-style emoji picker: search, category tabs, recently used, every Unicode emoji. */
export const EmojiPicker: React.FC<EmojiPickerProps> = ({ onPick, onClose, x, y, closeOnPick }) => {
  const ref = useRef<HTMLDivElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const [groups, setGroups] = useState<EmojiGroup[] | null>(null);
  const [query, setQuery] = useState('');
  const [recent, setRecent] = useState<string[]>(readRecent);
  const [pos, setPos] = useState({ left: x, top: y });

  useEffect(() => {
    let live = true;
    void loadEmojis().then((g) => live && setGroups(g));
    return () => {
      live = false;
    };
  }, []);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const { width, height } = el.getBoundingClientRect();
    setPos({
      left: Math.max(8, Math.min(x, window.innerWidth - width - 8)),
      top: Math.max(8, Math.min(y, window.innerHeight - height - 8)),
    });
  }, [x, y, groups]);

  useEffect(() => {
    const onDown = (e: MouseEvent) => {
      if (!ref.current?.contains(e.target as Node)) onClose();
    };
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    document.addEventListener('mousedown', onDown);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDown);
      document.removeEventListener('keydown', onKey);
    };
  }, [onClose]);

  const visible = useMemo<EmojiGroup[]>(() => {
    if (!groups) return [];
    const q = query.trim().toLowerCase();
    if (q) {
      const hits = groups.flatMap((g) => g.emojis.filter(([, name]) => name.includes(q)));
      return [{ group: 'Search results', emojis: hits }];
    }
    const recentGroup: EmojiGroup[] = recent.length ? [{ group: 'Recently used', emojis: recent.map((e) => [e, e]) }] : [];
    return [...recentGroup, ...groups];
  }, [groups, query, recent]);

  const pick = (emoji: string) => {
    rememberEmoji(emoji);
    setRecent(readRecent());
    onPick(emoji);
    if (closeOnPick) onClose();
  };

  const jumpTo = (group: string) => {
    setQuery('');
    requestAnimationFrame(() => {
      gridRef.current?.querySelector(`[data-group="${CSS.escape(group)}"]`)?.scrollIntoView({ block: 'start' });
    });
  };

  return (
    <div
      ref={ref}
      className="pulse-emoji-picker"
      style={{ left: pos.left, top: pos.top }}
      role="dialog"
      aria-label="Emoji picker"
      onMouseDown={(e) => e.preventDefault()} // keep focus (and the caret) in the message box
    >
      <div className="pulse-emoji-tabs">
        {['Recently used', ...(groups ?? []).map((g) => g.group)]
          .filter((g) => g !== 'Recently used' || recent.length > 0)
          .map((g) => (
            <button key={g} type="button" title={g} aria-label={g} onClick={() => jumpTo(g)}>
              {GROUP_ICONS[g] ?? <Smile size={16} />}
            </button>
          ))}
      </div>
      <label className="pulse-emoji-search">
        <Search size={14} />
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onMouseDown={(e) => e.stopPropagation()}
          placeholder="Search emoji"
          aria-label="Search emoji"
        />
      </label>
      <div className="pulse-emoji-grid" ref={gridRef}>
        {!groups && <div className="pulse-emoji-empty">Loading…</div>}
        {groups && visible.every((g) => g.emojis.length === 0) && <div className="pulse-emoji-empty">No emoji found</div>}
        {visible.map((g) =>
          g.emojis.length ? (
            <section key={g.group} data-group={g.group}>
              <h4>{g.group}</h4>
              <div className="pulse-emoji-cells">
                {g.emojis.map(([emoji, name]) => (
                  <button key={emoji} type="button" title={name} aria-label={name} onClick={() => pick(emoji)}>
                    {emoji}
                  </button>
                ))}
              </div>
            </section>
          ) : null
        )}
      </div>
    </div>
  );
};

export default EmojiPicker;
